from __future__ import annotations

import os
import platform
from datetime import datetime, timezone
from functools import lru_cache
import importlib

try:
    # Python 3.8+
    from importlib import metadata as importlib_metadata  # type: ignore
except Exception:  # pragma: no cover
    import importlib_metadata  # type: ignore

__all__ = ["version_info"]


def _infer_root_package() -> str:
    # Use the top-level package name as a best-effort service/package identifier
    parts = (__name__ or "").split(".")
    return parts[0] if parts else "app"


def _env(name: str) -> str | None:
    val = os.getenv(name)
    return val if val and val.strip() else None


def _resolve_version(root_pkg: str) -> str:
    # Prefer explicit env override
    if (v := _env("APP_VERSION")):
        return v
    # Try __version__ on root package
    try:
        pkg = importlib.import_module(root_pkg)
        v = getattr(pkg, "__version__", None)
        if isinstance(v, str) and v.strip():
            return v
    except Exception:
        pass
    # Try distribution metadata (may differ from module name)
    try:
        return importlib_metadata.version(root_pkg)
    except Exception:
        pass
    return "unknown"


def _resolve_build_date() -> str | None:
    # BUILD_DATE as ISO 8601 takes precedence
    if (d := _env("BUILD_DATE")):
        return d
    # SOURCE_DATE_EPOCH as seconds since epoch (reproducible builds)
    if (epoch := _env("SOURCE_DATE_EPOCH")):
        try:
            ts = datetime.fromtimestamp(int(epoch), tz=timezone.utc)
            return ts.isoformat().replace("+00:00", "Z")
        except Exception:
            pass
    return None


def _resolve_git_commit() -> str | None:
    return _env("GIT_COMMIT") or _env("GITHUB_SHA")


@lru_cache(maxsize=1)
def version_info() -> dict:
    """Return service/package version details for health and diagnostics.

    Keys:
      - name: service or package name (env SERVICE_NAME or root package)
      - version: semantic version string if known, else "unknown"
      - git_commit: commit SHA if provided via env
      - build_date: ISO 8601 UTC build timestamp if provided
      - python: Python runtime version
      - platform: OS/platform descriptor
    """
    root_pkg = _infer_root_package()

    return {
        "name": _env("SERVICE_NAME") or root_pkg,
        "version": _resolve_version(root_pkg),
        "git_commit": _resolve_git_commit(),
        "build_date": _resolve_build_date(),
        "python": platform.python_version(),
        "platform": platform.platform(),
    }
